parameters.jsCode:
// Nó "Interpretar mensagem".
// Lê o evento enviado pelo WAHA e a configuração (config/chatbot.json) e decide
// o que fazer: ignorar, processar (responder), pausar ou reativar o robô.
// Para mudar respostas e palavras-chave, edite config/chatbot.json, não este código.

const corpo = $('Webhook WAHA').first().json.body ?? {};

let cfg;
try {
  const bruto = String($('Extrair configuração').first().json.data ?? '').replace(/^﻿/, '');
  cfg = JSON.parse(bruto);
} catch (e) {
  throw new Error('config/chatbot.json inválido ou ilegível: ' + e.message);
}

// No v2 os campos {{...}} das mensagens gerais vêm de "produtora"; no v1, de "evento".
const evento = cfg.produtora ?? cfg.evento ?? {};
const mensagens = cfg.mensagens ?? {};
const humano = cfg.atendimento_humano ?? {};
const prot = cfg.protecoes ?? {};

// ---------- utilitários ----------

const numero = (valor, padrao) => {
  const n = Number(valor);
  return valor === null || valor === undefined || valor === '' || !Number.isFinite(n) ? padrao : n;
};

// Minúsculas, sem acentos, sem pontuação, espaços simples. "#" é mantido para os comandos.
const normalizar = (texto) =>
  String(texto ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9#]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ');

// Troca {{campo}} pelo valor de mesmo nome em "evento".
const preencher = (texto) =>
  String(texto ?? '').replace(/\{\{\s*([\w-]+)\s*\}\}/g, (original, chave) => {
    const valor = evento[chave] ?? evento[chave.toLowerCase()];
    return valor === undefined || valor === null || typeof valor === 'object' ? original : String(valor);
  });

// Nos logs o contato aparece só pelos 4 últimos dígitos.
const mascarar = (id) => {
  const digitos = String(id ?? '').split('@')[0].replace(/\D/g, '');
  return digitos ? '***' + digitos.slice(-4) : 'desconhecido';
};

// Final do identificador da mensagem (não contém o telefone).
const finalDoId = (id) => {
  const partes = String(id ?? '').split('_');
  const chave = partes.length >= 3 ? partes[2] : partes[partes.length - 1];
  return chave.replace(/[^A-Za-z0-9]/g, '').slice(-8) || 'sem-id';
};

const base = {
  evento: String(corpo.event ?? ''),
  sessao: String(corpo.session ?? 'default'),
};
const ignorar = (motivo, extra = {}) => [{ json: { ...base, ...extra, acao: 'ignorar', motivo } }];

// ---------- estado da sessão ----------
// O Redis guarda "<momento em ms>|<status>" do último evento de status do WhatsApp
// (STARTING, WORKING, STOPPED...). Esse momento marca quando o robô foi ligado pela
// última vez: o que foi enviado antes disso é mensagem pendente e não é respondido.

const estadoGuardado = String(($('Redis: estado da sessão').first().json ?? {}).sessao ?? '');
const ultimoStatusMs = Number(estadoGuardado.split('|')[0]) || 0;

if (base.evento === 'session.status') {
  const status = String(corpo.payload?.status ?? '');
  const informado = numero(corpo.timestamp, Date.now());
  const momentoMs = Math.min(informado < 1e12 ? informado * 1000 : informado, Date.now());
  // Eventos atrasados (reenviados pelo WAHA) não podem voltar o relógio.
  if (momentoMs < ultimoStatusMs) return ignorar('status_da_sessao', { detalhe: status });
  return [
    {
      json: {
        ...base,
        acao: 'sessao',
        detalhe: status,
        chaveSessao: 'sessao:' + base.sessao,
        valorSessao: Math.round(momentoMs) + '|' + status,
      },
    },
  ];
}

// ---------- filtros ----------

if (base.evento !== 'message' && base.evento !== 'message.any') {
  return ignorar('evento_nao_tratado');
}

const p = corpo.payload;
if (!p || typeof p !== 'object') {
  return ignorar('payload_ausente');
}

const de = String(p.from ?? '');
const para = String(p.to ?? '');
const doProprioNumero = p.fromMe === true;
// Em mensagens enviadas pelo próprio número, a conversa é o destinatário.
const chatId = doProprioNumero ? para || de : de;
const idMensagem = String(p.id ?? corpo.id ?? '');
const info = { contato: mascarar(chatId), msg: finalDoId(idMensagem) };

if (!chatId) return ignorar('remetente_ausente', info);
if (/@g\.us$/i.test(chatId) || /@g\.us$/i.test(de)) return ignorar('grupo', info);
if (/@newsletter$/i.test(chatId)) return ignorar('canal', info);
if (/@broadcast$/i.test(chatId)) return ignorar('status_ou_lista_de_transmissao', info);
if (!/@(c\.us|lid|s\.whatsapp\.net)$/i.test(chatId)) return ignorar('tipo_de_conversa_nao_suportado', info);

const texto = typeof p.body === 'string' ? p.body : '';

// Dados para a tela "Conversas" do painel. Ficam só no arquivo conversas-AAAA-MM-DD.log,
// apagado depois de alguns dias (CONVERSAS_RETENCAO_DIAS); o log de atividade não os recebe.
// No WAHA GOWS o contato costuma chegar como @lid; o telefone vem em _data.Info.SenderAlt
// (mensagens recebidas) ou RecipientAlt (mensagens do próprio número).
const infoWhatsApp = (p._data && typeof p._data === 'object' && p._data.Info && typeof p._data.Info === 'object') ? p._data.Info : {};
const telefoneDe = (id) => {
  const [usuario, dominio] = String(id ?? '').split('@');
  const digitos = String(usuario ?? '').split(':')[0].replace(/\D/g, '');
  return /^(c\.us|s\.whatsapp\.net)$/i.test(dominio ?? '') && digitos.length >= 8 ? digitos : '';
};
info.registro = {
  conversa: chatId,
  telefone: telefoneDe(chatId) || telefoneDe(doProprioNumero ? infoWhatsApp.RecipientAlt : infoWhatsApp.SenderAlt),
  // Nas mensagens do próprio número o PushName é o do atendente, não o do contato.
  nome: doProprioNumero ? '' : String(infoWhatsApp.PushName ?? p.notifyName ?? '').trim().slice(0, 80),
  texto: texto.slice(0, 4000),
  midia: p.hasMedia === true,
};
const normalizado = normalizar(texto);

const chavePausa = 'pausa:' + chatId;
const horasPausa = Math.max(numero(humano.horas_pausa, 24), 0.25);
const ttlPausa = Math.round(horasPausa * 3600);
const agoraIso = new Date().toISOString();

// Enviadas pela API são as respostas do próprio robô: nunca responder (evita laço).
if (doProprioNumero && String(p.source ?? '').toLowerCase() === 'api') return ignorar('enviada_pelo_robo', info);

// Mensagens antigas (por exemplo, as que o WhatsApp entrega de uma vez ao reconectar) não
// são tratadas, sejam do contato ou comandos do atendente.
const carimbo = numero(p.timestamp, 0);
const carimboSegundos = carimbo > 1e12 ? carimbo / 1000 : carimbo;
const idadeMaxima = numero(prot.idade_maxima_mensagem_segundos, 120);
if (carimboSegundos > 0 && idadeMaxima > 0 && Date.now() / 1000 - carimboSegundos > idadeMaxima) {
  return ignorar('mensagem_antiga', info);
}

// Mensagens enviadas enquanto o robô estava desligado ("conversas em aberto") chegam todas
// de uma vez quando ele é ligado. Não são respondidas, a menos que a configuração peça.
// A folga de 2 segundos cobre o arredondamento do horário informado pelo WhatsApp.
const responderPendentes = prot.responder_mensagens_recebidas_offline === true;
if (!responderPendentes && ultimoStatusMs > 0 && carimboSegundos > 0 && (carimboSegundos + 2) * 1000 < ultimoStatusMs) {
  return ignorar('recebida_com_o_robo_desligado', info);
}

// ---------- mensagens enviadas pelo próprio número ----------

if (doProprioNumero) {
  // Digitadas no celular pelo atendente: só interessam os comandos.
  const comandoReativar = normalizar(humano.comando_reativar ?? '#bot');
  const comandoPausar = normalizar(humano.comando_pausar ?? '#humano');
  const comum = { ...base, ...info, chatId, chavePausa };

  if (normalizado && normalizado === comandoReativar) {
    const aviso = preencher(mensagens.reativado).trim() || 'O atendimento automático foi reativado. Digite menu para ver as opções.';
    return [{ json: { ...comum, acao: 'reativar', resposta: aviso } }];
  }
  if (normalizado && normalizado === comandoPausar) {
    return [{ json: { ...comum, acao: 'pausar', ttlPausa, valorPausa: agoraIso + '|operador' } }];
  }
  // Qualquer outra mensagem digitada no celular (texto, foto, áudio) significa que uma pessoa
  // assumiu a conversa: o robô para de responder a esse contato, como no comando de pausa.
  // As respostas do próprio robô saem pela API e já foram descartadas acima.
  if (humano.pausar_quando_atendente_responder !== false) {
    return [{ json: { ...comum, acao: 'pausar', motivo: 'atendente_respondeu', ttlPausa, valorPausa: agoraIso + '|atendente_respondeu' } }];
  }
  return ignorar('enviada_pelo_atendente', info);
}

// ---------- mensagens recebidas ----------

if (!texto.trim()) {
  const responderMidia = p.hasMedia === true && prot.responder_midia_com_menu !== false;
  if (!responderMidia) return ignorar('sem_texto', info);
}

// "opção 2", "numero 3" etc. valem como "2", "3".
let alvo = normalizado.replace(/#/g, ' ').trim().replace(/\s+/g, ' ');
const comPrefixo = alvo.match(/^(?:opcao|numero|item|op)\s+(\d{1,2})$/);
if (comPrefixo) alvo = comPrefixo[1];

const lista = (valores) => (Array.isArray(valores) ? valores : []).map(normalizar).filter(Boolean);

// A escolha da resposta ocorre depois da deduplicação, da pausa e do agrupamento.
// Assim o fallback usa o contexto atualizado e mensagens descartadas não o avançam.

const atraso = prot.atraso_resposta_segundos ?? {};
const atrasoMinimo = Math.max(numero(atraso.min, 1), 0);
const atrasoMaximo = Math.max(numero(atraso.max, 3), atrasoMinimo);
const atrasoSegundos = Math.round((atrasoMinimo + Math.random() * (atrasoMaximo - atrasoMinimo)) * 10) / 10;

// Várias mensagens seguidas do mesmo contato recebem UMA resposta: espera-se este tempo e
// só a última mensagem da sequência é respondida.
const agruparSegundos = Math.min(Math.max(numero(prot.agrupar_mensagens_segundos, 4), 0), 30);

// Palavras com que o próprio contato sai do atendimento humano e volta ao robô.
const voltar = Boolean(alvo) && lista(humano.palavras_para_voltar ?? ['menu']).includes(alvo);

const chaveMensagem = idMensagem || chatId + ':' + carimbo;

return [
  {
    json: {
      ...base,
      ...info,
      acao: 'processar',
      chatId,
      config: cfg,
      texto,
      midia: !texto.trim() && p.hasMedia === true,
      chaveConversa: 'conversa:' + base.sessao + ':' + chatId,
      atrasoSegundos,
      agruparSegundos,
      voltar,
      chaveMensagem,
      carimboSegundos,
      responderPendentes,
      chavePausa,
      ttlPausa,
      valorPausa: agoraIso + '|cliente',
      chaves: {
        dedupe: 'dedupe:' + chaveMensagem,
        ultima: 'ultima:' + chatId,
        porHora: 'taxa:' + chatId,
      },
      ttl: {
        dedupe: 86400,
        ultima: 120,
        porHora: 3600,
        iguais: Math.max(Math.round(numero(prot.janela_respostas_iguais_minutos, 10) * 60), 60),
      },
      limites: {
        mensagensPorHora: Math.max(numero(prot.max_mensagens_por_hora, 40), 1),
        respostasIguais: Math.max(numero(prot.max_respostas_iguais, 3), 1),
      },
    },
  },
];

// Nó "Verificar duplicidade e pausa".
// Decide o caminho da mensagem:
//   parar  - já foi vista (mesmo ID) ou o contato está em atendimento humano;
//   voltar - o contato está em atendimento humano e digitou a palavra para voltar ao robô;
//   seguir - atendimento normal.

const base = $('Interpretar mensagem').first().json;

const contador = Number(Object.values($('Redis: deduplicar').first().json ?? {})[0]) || 0;
const pausa = ($('Redis: contato em atendimento?').first().json ?? {}).pausa;
const emAtendimentoHumano = pausa !== null && pausa !== undefined && pausa !== '';

let rota = 'seguir';
let motivo = '';

if (contador > 1) {
  rota = 'parar';
  motivo = 'mensagem_duplicada';
} else if (emAtendimentoHumano && base.voltar) {
  rota = 'voltar';
} else if (emAtendimentoHumano) {
  rota = 'parar';
  motivo = 'em_atendimento_humano';
}

return [{ json: { ...base, rota, motivo } }];

// Nó "Verificar sequência e sessão" (roda depois da espera por mensagens em sequência).
// Só deixa seguir a última mensagem de uma sequência do mesmo contato e confere DE NOVO se
// a mensagem não é uma pendência de quando o robô estava desligado. A segunda conferência
// cobre o caso de a mensagem pendente ter sido lida antes de o robô registrar que foi ligado.

const base = $('Interpretar mensagem').first().json;

const ultima = ($('Redis: ler última mensagem').first().json ?? {}).ultima;
const estado = String(($('Redis: reler estado da sessão').first().json ?? {}).sessao ?? '');
const ultimoStatusMs = Number(estado.split('|')[0]) || 0;

let seguir = true;
let motivo = '';

if (ultima && ultima !== base.chaveMensagem) {
  seguir = false;
  motivo = 'agrupada_com_mensagem_seguinte';
} else if (
  !base.responderPendentes &&
  ultimoStatusMs > 0 &&
  base.carimboSegundos > 0 &&
  (base.carimboSegundos + 2) * 1000 < ultimoStatusMs
) {
  seguir = false;
  motivo = 'recebida_com_o_robo_desligado';
}

return [{ json: { ...base, seguir, motivo } }];

// A espera pela conversa também pode ter sido atravessada por uma pausa do
// operador ou por uma mudança de sessão. Confere os valores relidos sob a trava.
const base = $('Interpretar mensagem').first().json;
const ultima = ($('Redis: conferir última após trava').first().json ?? {}).ultima;
const pausa = ($('Redis: conferir pausa após trava').first().json ?? {}).pausa;
const sessao = String(($('Redis: conferir sessão após trava').first().json ?? {}).sessao ?? '');
const ultimoStatusMs = Number(sessao.split('|')[0]) || 0;
let motivo = '';

if (ultima && ultima !== base.chaveMensagem) {
  motivo = 'agrupada_com_mensagem_seguinte';
} else if (pausa !== null && pausa !== undefined && pausa !== '') {
  // Mesmo um menu recebido antes da nova pausa respeita a ação posterior do operador.
  motivo = 'em_atendimento_humano';
} else if (
  !base.responderPendentes && ultimoStatusMs > 0 && base.carimboSegundos > 0 &&
  (base.carimboSegundos + 2) * 1000 < ultimoStatusMs
) {
  motivo = 'recebida_com_o_robo_desligado';
}

return [{ json: { ...base, seguir: !motivo, motivo } }];

const Chatbot = (() => { const module = { exports: {} };
// Motor compartilhado pelo n8n e pelo simulador. Sem acesso a arquivos ou rede.
// O estado contém somente contadores, IDs e a assinatura da última resposta.

function normalizar(texto) {
  return String(texto ?? '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9#]+/g, ' ').trim().replace(/\s+/g, ' ');
}

const SINONIMOS = {
  compro: 'comprar', comprando: 'comprar', compra: 'comprar', adquirir: 'comprar',
  ingresso: 'ingresso', ingressos: 'ingresso', ingreco: 'ingresso', ingrecos: 'ingresso', precos: 'preco', valores: 'valor',
  horarios: 'horario', enderecos: 'endereco', informacoes: 'informacao',
};
const VAZIAS = new Set(('a o as os um uma uns umas de do da dos das no na nos nas em e ou para pra pro por ' +
  'que qual quais eu voce voces meu minha meus minhas seu sua seus suas favor pfv pf ' +
  'preciso pode podem poderia quero queria gostaria saber dizer me mim com uma ser esta ta vai').split(' '));
// Palavras que aparecem em qualquer assunto e por isso não identificam nenhum sozinhas.
const GENERICAS = new Set(['ingresso', 'evento', 'ajuda', 'informacao', 'link', 'onde', 'como', 'funciona',
  'baile', 'bailes', 'festa', 'festas', 'show', 'role', 'oficial', 'nao']);
const MOLDURA_PERGUNTA = new Set(('posso podemos consigo encontro encontrar acesso acessar ver vejo ' +
  'esta estao sera serao quando quanto custa custam acontecer acontece faco faz fazer levar levo ' +
  'falar falo tenho tem ter permitido permitida permitidos permitidas').split(' '));
const lista = (valor) => Array.isArray(valor) ? valor.filter((v) => typeof v === 'string' && v.trim()) : [];
const canonico = (texto) => normalizar(texto).split(' ').map((p) => SINONIMOS[p] || p).join(' ');
const termos = (texto) => [...new Set(canonico(texto).split(' ').filter((p) => p && !VAZIAS.has(p)))];
const especificos = (texto) => termos(texto).filter((p) => !GENERICAS.has(p) && !/^\d+$/.test(p));
const contem = (texto, frase) => frase && (' ' + texto + ' ').includes(' ' + frase + ' ');

function assinatura(texto) {
  let valor = 2166136261;
  for (let i = 0; i < texto.length; i += 1) valor = Math.imul(valor ^ texto.charCodeAt(i), 16777619);
  return (valor >>> 0).toString(16);
}

function numeroDaOpcao(opcao) {
  return lista(opcao.palavras_exatas).map(normalizar).find((p) => /^\d{1,2}$/.test(p)) || '';
}

function tituloDaOpcao(opcao) {
  return String(opcao.titulo || opcao.id || 'Opção').replace(/[\r\n]+/g, ' ').trim();
}

function pontuar(opcao, texto) {
  const frase = canonico(texto);
  let valor = 0;
  let origem = 'palavra_chave';
  const melhorar = (pontos, tipo) => {
    if (pontos > valor) { valor = pontos; origem = tipo; }
  };

  for (const palavra of lista(opcao.palavras_exatas)) {
    if (canonico(palavra) === frase) melhorar(280, 'palavra_chave');
  }
  for (const palavra of lista(opcao.palavras_chave)) {
    const chave = canonico(palavra);
    if (frase === chave) melhorar(260, 'palavra_chave');
    else if (contem(frase, chave)) {
      if (especificos(chave).length) melhorar(100, 'palavra_chave');
      // "ajuda" e "ingresso" isolados podem ser úteis; dentro de outra pergunta
      // não são evidência suficiente para substituir o assunto principal.
      else if (termos(frase).length === 1) melhorar(80, 'palavra_chave');
    }
  }

  const termosDaFrase = new Set(termos(frase));
  for (const pergunta of lista(opcao.perguntas)) {
    const exemplo = canonico(pergunta);
    if (frase === exemplo) melhorar(300, 'pergunta');
    else if (contem(frase, exemplo) && especificos(exemplo).length) melhorar(200, 'pergunta');
    else {
      // O mesmo verbo pode aparecer em dúvidas sobre assuntos diferentes.
      // Só aproximar exemplos quando o assunto completo continua presente.
      const assunto = especificos(exemplo).filter((p) => !MOLDURA_PERGUNTA.has(p));
      if (assunto.length && assunto.every((p) => termosDaFrase.has(p))) {
        melhorar(75 + Math.min(assunto.length, 3) * 10, 'pergunta');
      }
    }
  }

  const titulo = especificos(opcao.titulo).filter((p) => !MOLDURA_PERGUNTA.has(p));
  if (titulo.some((p) => termosDaFrase.has(p))) melhorar(80, 'titulo');
  return { opcao, valor, origem };
}

// Uma inserção, remoção, substituição ou troca de letras vizinhas. Aplicada
// somente a termos com pelo menos seis letras e correção única no vocabulário.
function erroPequeno(a, b) {
  if (a === b || Math.abs(a.length - b.length) > 1) return false;
  if (a.length === b.length) {
    const diferentes = [];
    for (let i = 0; i < a.length; i += 1) if (a[i] !== b[i]) diferentes.push(i);
    return diferentes.length === 1 || (diferentes.length === 2 &&
      diferentes[1] === diferentes[0] + 1 && a[diferentes[0]] === b[diferentes[1]] && a[diferentes[1]] === b[diferentes[0]]);
  }
  const menor = a.length < b.length ? a : b;
  const maior = a.length < b.length ? b : a;
  let i = 0;
  while (i < menor.length && menor[i] === maior[i]) i += 1;
  return menor.slice(i) === maior.slice(i + 1);
}

function corrigir(texto, opcoes) {
  const vocabulario = [...new Set(opcoes.flatMap((opcao) =>
    [...lista(opcao.palavras_exatas), ...lista(opcao.palavras_chave), ...lista(opcao.perguntas), opcao.titulo || '']
      .flatMap(especificos)))].filter((p) => p.length >= 6);
  const conhecidos = new Set(vocabulario);
  return canonico(texto).split(' ').map((palavra) => {
    if (palavra.length < 6 || conhecidos.has(palavra)) return palavra;
    const candidatos = vocabulario.filter((v) => erroPequeno(palavra, v));
    return candidatos.length === 1 ? candidatos[0] : palavra;
  }).join(' ');
}

function ehSaudacao(texto, cfg) {
  const saudacoes = lista(cfg.saudacoes).length ? lista(cfg.saudacoes) : ['oi', 'ola', 'bom dia', 'boa tarde', 'boa noite', 'menu', 'inicio'];
  let restante = normalizar(texto);
  let encontrou = false;
  for (const palavra of saudacoes.map(normalizar).sort((a, b) => b.length - a.length)) {
    if (contem(restante, palavra)) {
      encontrou = true;
      restante = (' ' + restante + ' ').split(' ' + palavra + ' ').join(' ').trim();
    }
  }
  const cortesia = new Set(('tudo bem td bom com voce voces por favor pfv pf me manda mande enviar mostre mostra ' +
    'o a um uma eu quero queria gostaria de saber informacao informacoes ver').split(' '));
  return encontrou && restante.split(' ').every((p) => !p || cortesia.has(p));
}

function ehAgradecimento(texto) {
  const palavras = normalizar(texto).split(' ');
  const agradece = new Set(['obrigado', 'obrigada', 'obg', 'valeu', 'agradeco']);
  const cortesia = new Set(['muito', 'muitissimo', 'ok', 'okay', 'certo', 'ta', 'bom', 'sim', 'pela', 'ajuda', 'por', 'tudo']);
  return palavras.some((p) => agradece.has(p)) && palavras.every((p) => agradece.has(p) || cortesia.has(p));
}

function resolver(configuracao, texto, estado = {}, contexto = {}) {
