  groq: { nome: 'Groq', url: 'https://api.groq.com/openai/v1/chat/completions', modelo: 'openai/gpt-oss-120b' },
  xai: { nome: 'xAI (Grok)', url: 'https://api.x.ai/v1/chat/completions', modelo: 'grok-4.3' },
